import { Octokit } from "@octokit/rest";

const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });
const [owner, repo, number] = ["cli", "cli", Number(process.argv[2] ?? 14640)];
const pr = { owner, repo, pull_number: number };

const { data } = await octokit.rest.pulls.get(pr);
const head = data.head.sha;
console.log(`#${number} by ${data.user.login}, head ${head.slice(0, 7)}`);

const commits = await octokit.paginate(octokit.rest.pulls.listCommits, { ...pr, per_page: 100 });
const pushers = new Set(commits.map((c) => c.author?.login).filter(Boolean));
console.log(`commits: ${commits.length}, by ${[...pushers].join(", ")}`);

const reviews = await octokit.paginate(octokit.rest.pulls.listReviews, { ...pr, per_page: 100 });
for (const r of reviews) {
  const where = r.commit_id === head ? "on the head" : `on ${r.commit_id.slice(0, 7)}, an older commit`;
  console.log(`review: ${r.user.login} (${r.user.type}) ${r.state} ${where}`);
}

const checks = await octokit.paginate(octokit.rest.checks.listForRef, { owner, repo, ref: head, per_page: 100 });
const byResult = Object.groupBy(checks, (c) => c.conclusion ?? "still running");
console.log("checks on the head:", Object.entries(byResult).map(([k, v]) => `${v.length} ${k}`).join(", "));
